values (
  'en-dc-villains-trivia',
  'DC Villains Trivia: From the Joker to Darkseid',
  'Eight questions on DC''s most iconic villains, from the Joker''s debut in Batman #1 to Darkseid, Lex Luthor, Harley Quinn and Arkham Asylum.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which 1940 comic did the Joker make his first appearance?","options":[{"id":"a","text":"Detective Comics #27","is_correct":false},{"id":"b","text":"Batman #1","is_correct":true},{"id":"c","text":"Action Comics #1","is_correct":false},{"id":"d","text":"Detective Comics #1","is_correct":false}],"explanation":"The Joker debuted in Batman #1 (spring 1940), created by Bill Finger, Bob Kane and Jerry Robinson."},{"id":"q2","question":"In which 1940 issue did Lex Luthor first appear?","options":[{"id":"a","text":"Action Comics #23","is_correct":true},{"id":"b","text":"Action Comics #1","is_correct":false},{"id":"c","text":"Superman #1","is_correct":false},{"id":"d","text":"Batman #1","is_correct":false}],"explanation":"Lex Luthor debuted in Action Comics #23 (April 1940), created by Jerry Siegel and Joe Shuster."},{"id":"q3","question":"Which New God rules the planet Apokolips?","options":[{"id":"a","text":"Mongul","is_correct":false},{"id":"b","text":"Brainiac","is_correct":false},{"id":"c","text":"Darkseid","is_correct":true},{"id":"d","text":"Lobo","is_correct":false}],"explanation":"Darkseid debuted in Superman''s Pal Jimmy Olsen #134 (1970), created by Jack Kirby for his Fourth World saga."},{"id":"q4","question":"Where did Harley Quinn first appear before joining the comics?","options":[{"id":"a","text":"The 1989 Batman film","is_correct":false},{"id":"b","text":"Batman: The Animated Series","is_correct":true},{"id":"c","text":"Batman #1","is_correct":false},{"id":"d","text":"The Super Friends cartoon","is_correct":false}],"explanation":"Paul Dini and Bruce Timm created her for the 1992 animated series; she crossed into the comics later."},{"id":"q5","question":"Which villain famously broke Batman''s back in the Knightfall storyline?","options":[{"id":"a","text":"Killer Croc","is_correct":false},{"id":"b","text":"Bane","is_correct":true},{"id":"c","text":"Deathstroke","is_correct":false},{"id":"d","text":"Ra''s al Ghul","is_correct":false}],"explanation":"In the 1993 Knightfall arc, Bane broke Batman''s spine and forced him to hand over the cowl."},{"id":"q6","question":"What is the Riddler''s real name?","options":[{"id":"a","text":"Edward Nygma","is_correct":true},{"id":"b","text":"Oswald Cobblepot","is_correct":false},{"id":"c","text":"Harvey Dent","is_correct":false},{"id":"d","text":"Victor Fries","is_correct":false}],"explanation":"Edward Nygma is the Riddler; Cobblepot is the Penguin, Dent is Two-Face and Fries is Mr. Freeze."},{"id":"q7","question":"Which Green Lantern villain fights with a yellow power ring fueled by fear?","options":[{"id":"a","text":"Atrocitus","is_correct":false},{"id":"b","text":"Sinestro","is_correct":true},{"id":"c","text":"Larfleeze","is_correct":false},{"id":"d","text":"Black Hand","is_correct":false}],"explanation":"Sinestro, the fallen Green Lantern, debuted in Green Lantern #7 (1961) and later founded the Sinestro Corps."},{"id":"q8","question":"What is Catwoman''s real name?","options":[{"id":"a","text":"Harleen Quinzel","is_correct":false},{"id":"b","text":"Pamela Isley","is_correct":false},{"id":"c","text":"Selina Kyle","is_correct":true},{"id":"d","text":"Dinah Lance","is_correct":false}],"explanation":"Selina Kyle debuted in Batman #1 (1940) as ''the Cat''; Quinzel is Harley Quinn, Isley is Poison Ivy and Lance is Black Canary."}]'::jsonb,
  null,
  array['dc villains', 'joker', 'dc comics', 'trivia', 'supervillains']::text[],
  3,
  'published',
