  '[{"id":"q1","question":"¿En qué cómic de 1940 apareció por primera vez el Joker?","options":[{"id":"a","text":"Detective Comics #27","is_correct":false},{"id":"b","text":"Batman #1","is_correct":true},{"id":"c","text":"Action Comics #1","is_correct":false},{"id":"d","text":"Detective Comics #1","is_correct":false}],"explanation":"El Joker debutó en Batman #1 (primavera de 1940), creado por Bill Finger, Bob Kane y Jerry Robinson."},{"id":"q2","question":"¿En qué número de 1940 apareció por primera vez Lex Luthor?","options":[{"id":"a","text":"Action Comics #23","is_correct":true},{"id":"b","text":"Action Comics #1","is_correct":false},{"id":"c","text":"Superman #1","is_correct":false},{"id":"d","text":"Batman #1","is_correct":false}],"explanation":"Lex Luthor debutó en Action Comics #23 (abril de 1940), creado por Jerry Siegel y Joe Shuster."},{"id":"q3","question":"¿Qué Nuevo Dios gobierna el planeta Apokolips?","options":[{"id":"a","text":"Mongul","is_correct":false},{"id":"b","text":"Brainiac","is_correct":false},{"id":"c","text":"Darkseid","is_correct":true},{"id":"d","text":"Lobo","is_correct":false}],"explanation":"Darkseid debutó en Superman''s Pal Jimmy Olsen #134 (1970), creado por Jack Kirby para su saga del Cuarto Mundo."},{"id":"q4","question":"¿Dónde apareció Harley Quinn por primera vez, antes de llegar a los cómics?","options":[{"id":"a","text":"La película Batman de 1989","is_correct":false},{"id":"b","text":"Batman: The Animated Series","is_correct":true},{"id":"c","text":"Batman #1","is_correct":false},{"id":"d","text":"La serie animada Super Friends","is_correct":false}],"explanation":"Paul Dini y Bruce Timm la crearon para la serie animada de 1992; años después pasó a los cómics."},{"id":"q5","question":"¿Qué villano rompió la espalda de Batman en la saga Knightfall?","options":[{"id":"a","text":"Killer Croc","is_correct":false},{"id":"b","text":"Bane","is_correct":true},{"id":"c","text":"Deathstroke","is_correct":false},{"id":"d","text":"Ra''s al Ghul","is_correct":false}],"explanation":"En la saga Knightfall de 1993, Bane le rompió la espalda a Batman y lo obligó a ceder el manto."},{"id":"q6","question":"¿Cuál es el nombre real de Riddler?","options":[{"id":"a","text":"Edward Nygma","is_correct":true},{"id":"b","text":"Oswald Cobblepot","is_correct":false},{"id":"c","text":"Harvey Dent","is_correct":false},{"id":"d","text":"Victor Fries","is_correct":false}],"explanation":"Edward Nygma es Riddler (el Acertijo); Cobblepot es el Pingüino, Dent es Dos Caras y Fries es Mr. Freeze."},{"id":"q7","question":"¿Qué villano de Linterna Verde pelea con un anillo amarillo alimentado por el miedo?","options":[{"id":"a","text":"Atrocitus","is_correct":false},{"id":"b","text":"Sinestro","is_correct":true},{"id":"c","text":"Larfleeze","is_correct":false},{"id":"d","text":"Black Hand","is_correct":false}],"explanation":"Sinestro, el Linterna Verde caído, debutó en Green Lantern #7 (1961) y luego fundó el Sinestro Corps."},{"id":"q8","question":"¿Cuál es el nombre real de Catwoman?","options":[{"id":"a","text":"Harleen Quinzel","is_correct":false},{"id":"b","text":"Pamela Isley","is_correct":false},{"id":"c","text":"Selina Kyle","is_correct":true},{"id":"d","text":"Dinah Lance","is_correct":false}],"explanation":"Selina Kyle debutó en Batman #1 (1940) como ''la Gata''; Quinzel es Harley Quinn, Isley es Hiedra Venenosa y Lance es Canario Negro."}]'::jsonb,
