values (
  'en-joker-trivia',
  'Joker Trivia: Gotham''s Clown Prince of Crime',
  'Eight questions on the Joker, Batman''s arch-enemy: his debut in Batman #1, The Killing Joke, Jason Todd, Arkham Asylum and his films.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which comic did the Joker first appear in 1940?","options":[{"id":"a","text":"Detective Comics #27","is_correct":false},{"id":"b","text":"Action Comics #1","is_correct":false},{"id":"c","text":"Batman #1","is_correct":true},{"id":"d","text":"World''s Finest Comics #1","is_correct":false}],"explanation":"The Joker debuted in Batman #1 in the spring of 1940, in a story where he poisoned his victims with his grin."},{"id":"q2","question":"Which trio is credited with creating the Joker?","options":[{"id":"a","text":"Bill Finger, Bob Kane and Jerry Robinson","is_correct":true},{"id":"b","text":"Jerry Siegel and Joe Shuster","is_correct":false},{"id":"c","text":"Jack Kirby and Joe Simon","is_correct":false},{"id":"d","text":"William Moulton Marston and H. G. Peter","is_correct":false}],"explanation":"Siegel and Shuster created Superman; Marston and Peter created Wonder Woman."},{"id":"q3","question":"Which 1988 graphic novel by Alan Moore tells a possible origin for the Joker?","options":[{"id":"a","text":"The Dark Knight Returns","is_correct":false},{"id":"b","text":"The Killing Joke","is_correct":true},{"id":"c","text":"Arkham Asylum","is_correct":false},{"id":"d","text":"Watchmen","is_correct":false}],"explanation":"The Killing Joke presents a failed comedian who falls into a vat of chemicals; The Dark Knight Returns is by Frank Miller."},{"id":"q4","question":"Whom does the Joker murder in the 1988 storyline \"A Death in the Family\"?","options":[{"id":"a","text":"Dick Grayson","is_correct":false},{"id":"b","text":"Tim Drake","is_correct":false},{"id":"c","text":"Barbara Gordon","is_correct":false},{"id":"d","text":"Jason Todd","is_correct":true}],"explanation":"Readers voted on Jason Todd''s fate by phone; the Joker beat the second Robin and left him in an explosion."},{"id":"q5","question":"Where is the Joker most often held when captured?","options":[{"id":"a","text":"Blackgate Penitentiary","is_correct":false},{"id":"b","text":"Belle Reve","is_correct":false},{"id":"c","text":"Arkham Asylum","is_correct":true},{"id":"d","text":"Stryker''s Island","is_correct":false}],"explanation":"Arkham is Gotham''s psychiatric hospital; Blackgate is a prison and Belle Reve is the Suicide Squad''s base."},{"id":"q6","question":"Who played the Joker in The Dark Knight (2008)?","options":[{"id":"a","text":"Jared Leto","is_correct":false},{"id":"b","text":"Jack Nicholson","is_correct":false},{"id":"c","text":"Heath Ledger","is_correct":true},{"id":"d","text":"Joaquin Phoenix","is_correct":false}],"explanation":"Ledger won a posthumous Oscar for the role; Nicholson played the Joker in 1989 and Phoenix in 2019."},{"id":"q7","question":"What nickname sums up the Joker''s criminal persona?","options":[{"id":"a","text":"The Dark Knight","is_correct":false},{"id":"b","text":"The Clown Prince of Crime","is_correct":true},{"id":"c","text":"The Caped Crusader","is_correct":false},{"id":"d","text":"The Man of Tomorrow","is_correct":false}],"explanation":"The Dark Knight and the Caped Crusader are Batman; the Man of Tomorrow is Superman."},{"id":"q8","question":"Who directed the 2019 solo film Joker?","options":[{"id":"a","text":"Matt Reeves","is_correct":false},{"id":"b","text":"Christopher Nolan","is_correct":false},{"id":"c","text":"Todd Phillips","is_correct":true},{"id":"d","text":"Tim Burton","is_correct":false}],"explanation":"Todd Phillips directed Joker, which won the Golden Lion at the Venice Film Festival before its release."}]'::jsonb,
  null,
