values (
  'en-harley-quinn-trivia',
  'Harley Quinn Trivia: From Animated Series to the Big Screen',
  'Eight questions on Harley Quinn, from her 1992 debut in Batman: The Animated Series to Dr. Harleen Quinzel, her hyenas and the Suicide Squad.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Where did Harley Quinn first appear?","options":[{"id":"a","text":"Batman #1","is_correct":false},{"id":"b","text":"The 1989 Batman film","is_correct":false},{"id":"c","text":"Batman: The Animated Series","is_correct":true},{"id":"d","text":"A 1960s comic","is_correct":false}],"explanation":"She debuted in 1992 in the episode \"Joker''s Favor\" and crossed into the comics with Mad Love in 1994."},{"id":"q2","question":"Who created Harley Quinn?","options":[{"id":"a","text":"Alan Moore and Brian Bolland","is_correct":false},{"id":"b","text":"Paul Dini and Bruce Timm","is_correct":true},{"id":"c","text":"Frank Miller and Lynn Varley","is_correct":false},{"id":"d","text":"Denny O''Neil and Neal Adams","is_correct":false}],"explanation":"Dini wrote the character and Timm designed her for Batman: The Animated Series."},{"id":"q3","question":"What is Harley Quinn''s real name?","options":[{"id":"a","text":"Selina Kyle","is_correct":false},{"id":"b","text":"Pamela Isley","is_correct":false},{"id":"c","text":"Barbara Gordon","is_correct":false},{"id":"d","text":"Harleen Quinzel","is_correct":true}],"explanation":"Dr. Harleen Quinzel was an Arkham psychiatrist before falling for the Joker."},{"id":"q4","question":"What was Harley''s job at Arkham Asylum?","options":[{"id":"a","text":"Psychiatrist","is_correct":true},{"id":"b","text":"Prison guard","is_correct":false},{"id":"c","text":"Nurse","is_correct":false},{"id":"d","text":"Reporter","is_correct":false}],"explanation":"Dr. Quinzel treated the Joker and fell in love with him during their therapy sessions."},{"id":"q5","question":"What oversized weapon is Harley Quinn best known for?","options":[{"id":"a","text":"A whip","is_correct":false},{"id":"b","text":"A giant mallet","is_correct":true},{"id":"c","text":"A katana","is_correct":false},{"id":"d","text":"A bow","is_correct":false}],"explanation":"Her giant wooden mallet is her signature; in the films she also swings a baseball bat."},{"id":"q6","question":"What are the names of Harley''s two pet hyenas?","options":[{"id":"a","text":"Salt and Pepper","is_correct":false},{"id":"b","text":"Ace and King","is_correct":false},{"id":"c","text":"Bud and Lou","is_correct":true},{"id":"d","text":"Bonnie and Clyde","is_correct":false}],"explanation":"Bud and Lou are named after the comedy duo Bud Abbott and Lou Costello."},{"id":"q7","question":"Which team does Harley Quinn belong to in the 2016 live-action film?","options":[{"id":"a","text":"Birds of Prey","is_correct":false},{"id":"b","text":"Justice League","is_correct":false},{"id":"c","text":"Suicide Squad","is_correct":true},{"id":"d","text":"Teen Titans","is_correct":false}],"explanation":"The 2016 film centers on the Suicide Squad; Harley leads Birds of Prey in her 2020 movie."},{"id":"q8","question":"Who plays Harley Quinn in the live-action films?","options":[{"id":"a","text":"Emma Stone","is_correct":false},{"id":"b","text":"Margot Robbie","is_correct":true},{"id":"c","text":"Scarlett Johansson","is_correct":false},{"id":"d","text":"Jennifer Lawrence","is_correct":false}],"explanation":"Margot Robbie debuted as Harley in Suicide Squad (2016) and starred in Birds of Prey (2020)."}]'::jsonb,
