values (
  'en-dc-comics-trivia',
  'DC Comics Trivia: Heroes, Cities and Landmark Issues',
  'Eight questions on DC Comics history: Action Comics #1, Detective Comics #27, Gotham, Metropolis, Watchmen and Crisis on Infinite Earths.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Which 1938 issue introduced Superman and launched the superhero genre?","options":[{"id":"a","text":"Detective Comics #27","is_correct":false},{"id":"b","text":"Action Comics #1","is_correct":true},{"id":"c","text":"Batman #1","is_correct":false},{"id":"d","text":"All Star Comics #3","is_correct":false}],"explanation":"Action Comics #1 (June 1938) introduced Superman, created by Jerry Siegel and Joe Shuster."},{"id":"q2","question":"In which 1939 issue did Batman first appear?","options":[{"id":"a","text":"Action Comics #1","is_correct":false},{"id":"b","text":"Batman #1","is_correct":false},{"id":"c","text":"Detective Comics #27","is_correct":true},{"id":"d","text":"All Star Comics #8","is_correct":false}],"explanation":"Batman debuted in Detective Comics #27 (May 1939); Wonder Woman appeared in All Star Comics #8 (1941)."},{"id":"q3","question":"What did the letters \"DC\" originally stand for?","options":[{"id":"a","text":"Dynamic Comics","is_correct":false},{"id":"b","text":"Detective Comics","is_correct":true},{"id":"c","text":"Deluxe Comics","is_correct":false},{"id":"d","text":"Digital Comics","is_correct":false}],"explanation":"The publisher took its initials from Detective Comics, the anthology series that introduced Batman."},{"id":"q4","question":"Who created Wonder Woman in 1941?","options":[{"id":"a","text":"Jerry Siegel","is_correct":false},{"id":"b","text":"Bob Kane","is_correct":false},{"id":"c","text":"William Moulton Marston","is_correct":true},{"id":"d","text":"Jack Kirby","is_correct":false}],"explanation":"Psychologist William Moulton Marston created Wonder Woman; artist H. G. Peter drew her first stories."},{"id":"q5","question":"Which fictional city does Batman protect?","options":[{"id":"a","text":"Metropolis","is_correct":false},{"id":"b","text":"Central City","is_correct":false},{"id":"c","text":"Star City","is_correct":false},{"id":"d","text":"Gotham City","is_correct":true}],"explanation":"Gotham is Batman''s home; Metropolis is Superman''s city and Central City is the Flash''s."},{"id":"q6","question":"Which hero calls Metropolis home?","options":[{"id":"a","text":"Superman","is_correct":true},{"id":"b","text":"Batman","is_correct":false},{"id":"c","text":"Green Arrow","is_correct":false},{"id":"d","text":"The Flash","is_correct":false}],"explanation":"Metropolis is Superman''s city; Green Arrow protects Star City and the Flash protects Central City."},{"id":"q7","question":"Which 1986 limited series by Alan Moore and Dave Gibbons deconstructed superheroes?","options":[{"id":"a","text":"The Dark Knight Returns","is_correct":false},{"id":"b","text":"Watchmen","is_correct":true},{"id":"c","text":"Kingdom Come","is_correct":false},{"id":"d","text":"Crisis on Infinite Earths","is_correct":false}],"explanation":"Watchmen (1986-87) follows retired heroes in a cold-war world; The Dark Knight Returns is by Frank Miller."},{"id":"q8","question":"Which 1985 crossover event rebooted DC continuity and collapsed its multiverse?","options":[{"id":"a","text":"Infinite Crisis","is_correct":false},{"id":"b","text":"Final Crisis","is_correct":false},{"id":"c","text":"Flashpoint","is_correct":false},{"id":"d","text":"Crisis on Infinite Earths","is_correct":true}],"explanation":"Crisis on Infinite Earths (1985-86) merged DC''s many Earths into a single continuity."}]'::jsonb,
  null,
  array['dc comics', 'superheroes', 'comics', 'trivia', 'history']::text[],
