  '[{"id":"q1","question":"¿Qué número de 1938 presentó a Superman e inauguró el género de superhéroes?","options":[{"id":"a","text":"Detective Comics #27","is_correct":false},{"id":"b","text":"Action Comics #1","is_correct":true},{"id":"c","text":"Batman #1","is_correct":false},{"id":"d","text":"All Star Comics #3","is_correct":false}],"explanation":"Action Comics #1 (junio de 1938) presentó a Superman, creado por Jerry Siegel y Joe Shuster."},{"id":"q2","question":"¿En qué número de 1939 apareció por primera vez Batman?","options":[{"id":"a","text":"Action Comics #1","is_correct":false},{"id":"b","text":"Batman #1","is_correct":false},{"id":"c","text":"Detective Comics #27","is_correct":true},{"id":"d","text":"All Star Comics #8","is_correct":false}],"explanation":"Batman debutó en Detective Comics #27 (mayo de 1939); la Mujer Maravilla apareció en All Star Comics #8 (1941)."},{"id":"q3","question":"¿Qué significaban originalmente las letras \"DC\"?","options":[{"id":"a","text":"Dynamic Comics","is_correct":false},{"id":"b","text":"Detective Comics","is_correct":true},{"id":"c","text":"Deluxe Comics","is_correct":false},{"id":"d","text":"Digital Comics","is_correct":false}],"explanation":"La editorial tomó sus iniciales de Detective Comics, la serie de antología donde debutó Batman."},{"id":"q4","question":"¿Quién creó a la Mujer Maravilla en 1941?","options":[{"id":"a","text":"Jerry Siegel","is_correct":false},{"id":"b","text":"Bob Kane","is_correct":false},{"id":"c","text":"William Moulton Marston","is_correct":true},{"id":"d","text":"Jack Kirby","is_correct":false}],"explanation":"El psicólogo William Moulton Marston creó a la Mujer Maravilla; el dibujante H. G. Peter ilustró sus primeras historias."},{"id":"q5","question":"¿Qué ciudad ficticia protege Batman?","options":[{"id":"a","text":"Metrópolis","is_correct":false},{"id":"b","text":"Ciudad Central","is_correct":false},{"id":"c","text":"Star City","is_correct":false},{"id":"d","text":"Gotham","is_correct":true}],"explanation":"Gotham es el hogar de Batman; Metrópolis es la ciudad de Superman y Ciudad Central la de Flash."},{"id":"q6","question":"¿Qué héroe vive en Metrópolis?","options":[{"id":"a","text":"Superman","is_correct":true},{"id":"b","text":"Batman","is_correct":false},{"id":"c","text":"Flecha Verde","is_correct":false},{"id":"d","text":"Flash","is_correct":false}],"explanation":"Metrópolis es la ciudad de Superman; Flecha Verde protege Star City y Flash protege Ciudad Central."},{"id":"q7","question":"¿Qué serie limitada de 1986, escrita por Alan Moore y dibujada por Dave Gibbons, deconstruyó a los superhéroes?","options":[{"id":"a","text":"The Dark Knight Returns","is_correct":false},{"id":"b","text":"Watchmen","is_correct":true},{"id":"c","text":"Kingdom Come","is_correct":false},{"id":"d","text":"Crisis en Tierras Infinitas","is_correct":false}],"explanation":"Watchmen (1986-87) sigue a héroes retirados en un mundo de guerra fría; The Dark Knight Returns es de Frank Miller."},{"id":"q8","question":"¿Qué evento de 1985 reinició la continuidad de DC y colapsó su multiverso?","options":[{"id":"a","text":"Crisis Infinita","is_correct":false},{"id":"b","text":"Crisis Final","is_correct":false},{"id":"c","text":"Flashpoint","is_correct":false},{"id":"d","text":"Crisis en Tierras Infinitas","is_correct":true}],"explanation":"Crisis en Tierras Infinitas (1985-86) fusionó las muchas Tierras de DC en una sola continuidad."}]'::jsonb,
